package cli_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestConfigCommands(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantExit   int
		wantStdout string
		wantStderr string
	}{
		// The happy paths whisper softly
		{"get existing key", []string{"config", "get", "database.host"}, 0, "localhost\n", ""},
		{"set new key", []string{"config", "set", "app.name", "serenity"}, 0, "", ""},
		{"list all", []string{"config", "list"}, 0, "", ""},

		// But the broken ones... they SCREAM
		{"get missing key", []string{"config", "get", "nonexistent"}, 1, "", "error: key not found\n"},
		{"no subcommand", []string{"config"}, 2, "", ""},
		{"invalid subcommand", []string{"config", "burn"}, 2, "", ""},
		{"set without value", []string{"config", "set", "key"}, 2, "", ""},
		{"delete missing", []string{"config", "delete", "ghost"}, 1, "", ""},

		// Flags dance in darkness
		{"format json", []string{"config", "list", "--format", "json"}, 0, "", ""},
		{"format invalid", []string{"config", "list", "--format", "binary"}, 2, "", ""},
		{"quiet suppresses", []string{"config", "set", "a", "b", "--quiet"}, 0, "", ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr, exit := runCLI(tt.args)
			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
			// Verify streams flow to proper channels
		})
	}
}

func TestFileSystemOperations(t *testing.T) {
	t.Run("init creates file", func(t *testing.T) {
		tmp := t.TempDir()
		cfg := filepath.Join(tmp, "config.yaml")
		runCLI([]string{"config", "init", "--config", cfg})
		if _, err := os.Stat(cfg); os.IsNotExist(err) {
			t.Error("config file not created")
		}
	})

	t.Run("permission denied", func(t *testing.T) {
		tmp := t.TempDir()
		os.Chmod(tmp, 0000)
		defer os.Chmod(tmp, 0755)
		_, stderr, exit := runCLI([]string{"config", "init", "--config", filepath.Join(tmp, "x")})
		if exit != 1 || stderr == "" {
			t.Error("should fail with permission error")
		}
	})

	t.Run("invalid YAML", func(t *testing.T) {
		tmp := t.TempDir()
		cfg := filepath.Join(tmp, "bad.yaml")
		os.WriteFile(cfg, []byte(":::broken:::"), 0644)
		_, _, exit := runCLI([]string{"config", "validate", "--config", cfg})
		if exit != 1 {
			t.Error("should reject invalid YAML")
		}
	})
}
